"""Isotropic TV inpainting using PDHG. No image content is generated by an AI model.

The shared-interior forward differences exactly match the supplied lecture's
sum over i=1..H-1, j=1..W-1. RGB uses a joint direction/channel l2 norm.
"""
import numpy as np


def gradient(u):
    return np.stack((u[1:, :-1] - u[:-1, :-1],
                     u[:-1, 1:] - u[:-1, :-1]), axis=-2)


def adjoint(p, shape):
    q = np.zeros(shape, dtype=p.dtype)
    q[1:, :-1] += p[:, :, 0]
    q[:-1, 1:] += p[:, :, 1]
    q[:-1, :-1] -= p[:, :, 0] + p[:, :, 1]
    return q


def total_variation(u):
    return float(np.linalg.norm(gradient(u), axis=(-2, -1)).sum())


class TVSolver:
    def __init__(self, observed, known):
        observed = np.asarray(observed, dtype=np.float64)
        known = np.asarray(known, dtype=bool)
        if observed.ndim != 3 or observed.shape[:2] != known.shape:
            raise ValueError('Image and mask shapes do not match')
        if min(known.shape) < 2 or observed.shape[2] not in (1, 3):
            raise ValueError('Expected H x W x (1 or 3) image')
        if not np.isfinite(observed).all() or observed.min() < 0 or observed.max() > 1:
            raise ValueError('Observed intensities must be finite and in [0,1]')
        if not known.any() or known.all():
            raise ValueError('Need both observed and missing pixels')
        # Deliberately discard anything supplied at missing positions.
        self.observed = np.where(known[..., None], observed, 0.)
        self.known = known.copy()
        self.u = self.observed.copy()
        self.bar = self.u.copy()
        self.p = np.zeros_like(gradient(self.u))
        self.iteration = 0
        self.tau = self.sigma = .30  # tau * sigma * ||D||^2 <= .72 < 1

    def step(self, count=1):
        for _ in range(count):
            self.p += self.sigma * gradient(self.bar)
            self.p /= np.maximum(1., np.linalg.norm(self.p, axis=(-2, -1)))[..., None, None]
            new = np.clip(self.u - self.tau * adjoint(self.p, self.u.shape), 0, 1)
            new[self.known] = self.observed[self.known]
            self.bar = 2 * new - self.u
            self.u = new
            self.iteration += 1

    def metrics(self):
        q = adjoint(self.p, self.u.shape)
        lower = float(np.sum(q[self.known] * self.observed[self.known])
                      + np.minimum(q[~self.known], 0).sum())
        tv = total_variation(self.u)
        return dict(iteration=self.iteration, tv=tv, lower_bound=lower,
                    relative_gap=max(0., tv - lower) / max(1., tv),
                    known_error=float(np.max(np.abs(self.u[self.known] - self.observed[self.known]))))

